(() => {
  'use strict';
  const canvas = document.getElementById('game'), ctx = canvas.getContext('2d');
  const mini = document.getElementById('minimap'), mctx = mini.getContext('2d');
  const feed = document.getElementById('feedCanvas'), fctx = feed.getContext('2d');
  const $ = id => document.getElementById(id);
  const W = 1200, H = 780, TAU = Math.PI * 2;
  const areas = [
    {id:'lab',name:'LABORATORY',sub:'Sector A · Capsule breach',r:[72,260,260,245],color:'#192c28'},
    {id:'west',name:'WEST CORRIDOR',sub:'Sector A · Main artery',r:[280,345,240,64],color:'#1c2a26'},
    {id:'main',name:'CENTRAL CORRIDOR',sub:'Sector B · Main artery',r:[500,345,300,64],color:'#1c2a26'},
    {id:'east',name:'EAST CORRIDOR',sub:'Sector C · Railway access',r:[770,345,80,64],color:'#1c2a26'},
    {id:'controlLink',name:'CONTROL ACCESS',sub:'Sector B · Restricted',r:[515,275,64,100],color:'#182a27'},
    {id:'control',name:'CONTROL ROOM',sub:'Sector B · Security operations',r:[440,155,210,145],color:'#192e2a'},
    {id:'upperLink',name:'NORTH PASSAGE',sub:'Sector C · Cold storage access',r:[620,220,205,50],color:'#1b2c29'},
    {id:'freezerLink',name:'FREEZER ACCESS',sub:'Sector C · Temperature warning',r:[790,270,60,100],color:'#172d32'},
    {id:'freezer',name:'FREEZER ROOM',sub:'Sector C · Movement impaired',r:[780,105,260,180],color:'#17333a'},
    {id:'railLink',name:'RAIL PLATFORM',sub:'Sector D · Mind the train',r:[810,390,60,90],color:'#252c29'},
    {id:'rail',name:'RAILWAY',sub:'Sector D · Active transit line',r:[790,465,330,190],color:'#272d29'},
    {id:'coreLink',name:'CORE ACCESS',sub:'Sector B · Elevator shaft',r:[390,395,76,145],color:'#292a25'},
    {id:'core',name:'THE CORE',sub:'Sector B · Elevator online',r:[305,520,260,205],color:'#2b2924'},
    {id:'ventA',name:'VENT NETWORK',sub:'Unlit · Crawlspace',r:[278,335,240,14],color:'#121a18',vent:true},
    {id:'ventB',name:'VENT NETWORK',sub:'Unlit · Crawlspace',r:[510,258,14,100],color:'#121a18',vent:true},
    {id:'ventC',name:'VENT NETWORK',sub:'Unlit · Crawlspace',r:[568,250,245,14],color:'#121a18',vent:true},
    {id:'ventD',name:'VENT NETWORK',sub:'Unlit · Crawlspace',r:[800,260,14,138],color:'#121a18',vent:true},
    {id:'ventE',name:'VENT NETWORK',sub:'Unlit · Crawlspace',r:[446,390,14,150],color:'#121a18',vent:true},
  ];
  const rooms = areas.filter(a=>!['west','main','east','controlLink','upperLink','freezerLink','railLink','coreLink'].includes(a.id));
  const nodes=[
    {x:190,y:380,area:'lab'},{x:365,y:377,area:'west'},{x:580,y:377,area:'main'},{x:790,y:377,area:'east'},
    {x:547,y:320,area:'controlLink'},{x:545,y:225,area:'control'},{x:710,y:245,area:'upperLink'},{x:900,y:195,area:'freezer'},
    {x:840,y:430,area:'railLink'},{x:955,y:550,area:'rail'},{x:430,y:475,area:'coreLink'},{x:430,y:620,area:'core'},
    {x:400,y:342,area:'ventA'},{x:517,y:305,area:'ventB'},{x:680,y:257,area:'ventC'},{x:807,y:340,area:'ventD'},{x:453,y:470,area:'ventE'}
  ];
  const links=[[0,1],[1,2],[2,3],[2,4],[4,5],[5,6],[6,7],[7,15],[3,8],[8,9],[1,10],[10,11],[12,13],[13,14],[14,15],[12,0],[13,4],[15,8],[16,10],[16,12]];
  const hides=[{x:112,y:300,label:'SPECIMEN CABINET',type:'cabinet'},{x:250,y:460,label:'STORAGE CRATE',type:'crate'},{x:475,y:200,label:'SERVER RACK',type:'rack'},{x:612,y:270,label:'CONSOLE BANK',type:'console'},{x:1010,y:250,label:'COLD LOCKER',type:'locker'},{x:1033,y:590,label:'CARGO PALLET',type:'crate'},{x:330,y:685,label:'CORE HOUSING',type:'rack'}];
  let dpr=1, scale=1, ox=0, oy=0, running=false, timeLeft=180, stamina=100, floor=1, floorChange=0;
  let crouching=false, flashlight=false, whistleCooldown=0, toastTimer=0, monitor=false, camIndex=0, muted=true, trainX=-100, trainDir=1, shake=0, caughtFlash=0;
  const keys={}, touch={up:false,down:false,left:false,right:false};
  const player={x:212,y:420,r:10,speed:122,alive:true,hidden:false,noise:0,face:0};
  const beast={x:165,y:330,r:15,speed:90,state:'search',target:null,alert:0,stun:0,face:0};
  const bots=[];
  const names=['MARA','JUNO','ELI','SATO','VEX','NIKO','REMY','TALA','ORIN'];
  const palette=['#85d5c0','#e4a866','#a7b6f0','#d685a2','#83ba87','#d1c26c','#9bb9cb','#ca8d64','#9bc985'];
  function bot(x,y,i){return {x,y,r:8,speed:70+Math.random()*15,name:names[i],color:palette[i],alive:true,target:null,route:[],routeAt:0,hideTimer:0,crouch:false,alert:0,face:0,decision:Math.random()*3};}
  const botStarts=[[150,450],[240,300],[560,225],[610,228],[695,245],[910,245],[870,530],[1020,530],[380,620]];
  botStarts.forEach((p,i)=>bots.push(bot(p[0],p[1],i)));
  function resize(){dpr=Math.min(devicePixelRatio||1,2);canvas.width=Math.floor(innerWidth*dpr);canvas.height=Math.floor(innerHeight*dpr);ctx.setTransform(dpr,0,0,dpr,0,0);scale=Math.min(innerWidth/W,innerHeight/H);ox=(innerWidth-W*scale)/2;oy=(innerHeight-H*scale)/2;}
  addEventListener('resize',resize);resize();
  function inside(x,y,r){return x>=r[0]&&x<=r[0]+r[2]&&y>=r[1]&&y<=r[1]+r[3];}
  function areaAt(x,y){let a=areas.find(a=>inside(x,y,a.r));return a||areas.find(a=>inside(x,y,a.r,));}
  function walkable(x,y){return areas.some(a=>inside(x,y,a.r));}
  function moveEntity(e,dx,dy){let nx=e.x+dx,ny=e.y+dy;if(walkable(nx,e.y))e.x=nx;if(walkable(e.x,ny))e.y=ny;}
  function clampEntity(e){if(walkable(e.x,e.y))return;let best=null,bd=Infinity;for(let a of areas){let [x,y,w,h]=a.r,cx=Math.max(x+3,Math.min(x+w-3,e.x)),cy=Math.max(y+3,Math.min(y+h-3,e.y)),d=(cx-e.x)**2+(cy-e.y)**2;if(d<bd){bd=d;best=[cx,cy];}}if(best){e.x=best[0];e.y=best[1];}}
  function graphRoute(from,to){let si=0,ti=0,sd=Infinity,td=Infinity;nodes.forEach((n,i)=>{let a=(n.x-from.x)**2+(n.y-from.y)**2,b=(n.x-to.x)**2+(n.y-to.y)**2;if(a<sd){sd=a;si=i}if(b<td){td=b;ti=i}});let q=[si],prev={ [si]:-1 };while(q.length){let n=q.shift();if(n===ti)break;for(const [a,b] of links){let next=a===n?b:b===n?a:-1;if(next>=0&&prev[next]===undefined){prev[next]=n;q.push(next)}}}let path=[];if(prev[ti]!==undefined){let n=ti;while(n!==-1){path.unshift(nodes[n]);n=prev[n]}}return path;}
  function steer(e,goal,speed,dt){if(!goal)return;let dx=goal.x-e.x,dy=goal.y-e.y,d=Math.hypot(dx,dy);if(d<10){e.routeAt=(e.routeAt||0)+1;return;}e.face=Math.atan2(dy,dx);let len=Math.min(d,speed*dt),mx=dx/d*len,my=dy/d*len;moveEntity(e,mx,my);}
  function findPath(e,target){e.route=graphRoute(e,target);e.routeAt=0;e.target=target;}
  function updateBots(dt){for(const b of bots){if(!b.alive)continue;b.decision-=dt;let threat=Math.hypot(b.x-beast.x,b.y-beast.y);if(threat<210){b.alert=Math.max(b.alert,5);b.hideTimer=Math.max(b.hideTimer,2+Math.random()*3);b.crouch=true;if(!b.target||b.decision<0){let s=hides.slice().sort((a,c)=>Math.hypot(c.x-beast.x,c.y-beast.y)-Math.hypot(a.x-beast.x,a.y-beast.y))[0];findPath(b,{x:s.x,y:s.y});b.decision=1.2;}}
      if(b.hideTimer>0){b.hideTimer-=dt;if(b.hideTimer<=0){b.crouch=false;b.target=null;}}
      if(!b.target||b.decision<=0){let opts=nodes.filter(n=>!areas.find(a=>a.id===n.area)?.vent);let n=opts[Math.floor(Math.random()*opts.length)];findPath(b,{x:n.x+(Math.random()-.5)*35,y:n.y+(Math.random()-.5)*25});b.decision=5+Math.random()*8;}
      if(b.target){let wp=b.route[b.routeAt];if(wp&&Math.hypot(wp.x-b.x,wp.y-b.y)>12)steer(b,wp,b.crouch?32:b.speed,dt);else steer(b,b.target,b.crouch?32:b.speed,dt);if(Math.hypot(b.x-b.target.x,b.y-b.target.y)<14)b.target=null;}
      b.x=Math.max(80,Math.min(1105,b.x));clampEntity(b);
    }}
  function chooseBeastTarget(){let candidates=[player,...bots.filter(b=>b.alive)];let audible=candidates.filter(t=>t.noise>0||t===player&&player.hidden&&false);let pool=audible.length?audible:candidates;pool.sort((a,b)=>Math.hypot(a.x-beast.x,a.y-beast.y)-Math.hypot(b.x-beast.x,b.y-beast.y));let t=pool[0];if(!t)return null;return {x:t.x,y:t.y,target:t};}
  function updateBeast(dt){if(beast.stun>0){beast.stun-=dt;return;}beast.alert=Math.max(0,beast.alert-dt*.3);let cands=[player,...bots.filter(b=>b.alive)];let seen=null,best=Infinity;for(const t of cands){let dist=Math.hypot(t.x-beast.x,t.y-beast.y),radius=(t===player?(crouching?95:flashlight?290:190):(t.crouch?100:180));let inDark=areas.some(a=>a.vent&&inside(t.x,t.y,a.r));if(inDark&&!(t===player&&flashlight))radius*=.42;if(t.noise>0)radius=Math.max(radius,330);if(dist<radius&&dist<best){best=dist;seen=t;}}
    if(seen){beast.target=seen;beast.state=best<120?'CHASE':'INVESTIGATE';beast.alert=1;}
    else if(!beast.target||Math.hypot(beast.target.x-beast.x,beast.target.y-beast.y)<22){beast.target=chooseBeastTarget()?.target||null;beast.state=beast.alert>.1?'SEARCH':'PATROL';}
    if(!beast.target)return;let target=beast.target,slow=areas.some(a=>a.id==='freezer'&&inside(beast.x,beast.y,a.r))?.53:1;let speed=(beast.state==='CHASE'?beast.speed*1.3:beast.speed)*slow;steer(beast,target,speed,dt);if(beast.state==='CHASE'&&Math.hypot(player.x-beast.x,player.y-beast.y)<23){lose();}for(const b of bots){if(b.alive&&Math.hypot(b.x-beast.x,b.y-beast.y)<22){b.alive=false;beast.target=null;toast(`${b.name} HAS BEEN TAKEN`);break;}}
  }
  function locFor(x,y){let a=areas.find(a=>inside(x,y,a.r));return a||areas[0];}
  function update(dt){if(!running)return;timeLeft=Math.max(0,timeLeft-dt);if(timeLeft<=0){win();return;}whistleCooldown=Math.max(0,whistleCooldown-dt);player.noise=Math.max(0,player.noise-dt);for(const b of bots)b.noise=Math.max(0,(b.noise||0)-dt);
    let x=(keys.d||keys.arrowright||touch.right?1:0)-(keys.a||keys.arrowleft||touch.left?1:0),y=(keys.s||keys.arrowdown||touch.down?1:0)-(keys.w||keys.arrowup||touch.up?1:0);let mag=Math.hypot(x,y);if(mag){x/=mag;y/=mag;player.face=Math.atan2(y,x);let run=(keys.shift||keys.run)&&stamina>0&&!crouching;let speed=crouching?58:run?215:128;let zone=locFor(player.x,player.y);if(zone.id==='freezer')speed*=.58;if(zone.vent)speed*=.68;moveEntity(player,x*speed*dt,y*speed*dt);player.noise=run?.9:.2;if(run)stamina=Math.max(0,stamina-28*dt);else stamina=Math.min(100,stamina+17*dt);}else{stamina=Math.min(100,stamina+21*dt);player.noise=0;}
    updateBots(dt);updateBeast(dt);trainX+=trainDir*310*dt;if(trainX>W+100){trainX=-280;}if(trainX<-280)trainX=W+100;floorChange=Math.max(0,floorChange-dt);if(toastTimer>0){toastTimer-=dt;if(toastTimer<=0)$('toast').classList.remove('show');}shake=Math.max(0,shake-dt*18);
    let loc=locFor(player.x,player.y);$('locationName').textContent=loc.name;$('locationSub').textContent=loc.id==='core'?`Sector B · Floor ${String(floor).padStart(2,'0')} · Elevator online`:loc.sub;
    $('staminaBar').style.width=`${stamina}%`;$('staminaText').textContent=`${Math.round(stamina)}%`;$('survivors').textContent=(1+bots.filter(b=>b.alive).length);$('clock').textContent=`${String(Math.floor(timeLeft/60)).padStart(2,'0')}:${String(Math.floor(timeLeft%60)).padStart(2,'0')}`;$('objective').textContent=beast.state==='CHASE'?'RUN. BREAK LINE OF SIGHT.':player.hidden?'You are hidden. Keep quiet.':'Stay hidden. Stay alive.';$('statusText').textContent=beast.state==='CHASE'?'ENTITY IN PURSUIT':'SURVIVE THE HUNT';document.querySelector('.objective-progress i').style.width=`${(1-timeLeft/180)*100}%`;
    let hint='';if(loc.id==='control'||loc.id==='controlLink')hint='[ E ] OPEN SECURITY MONITORS';if(loc.id==='core'||loc.id==='coreLink')hint='[ E ] CALL CORE ELEVATOR';$('interactHint').textContent=hint;$('monitorOpen').style.display=(loc.id==='control'||loc.id==='controlLink')?'block':'none';
    player.hidden=crouching&&hides.some(h=>Math.hypot(player.x-h.x,player.y-h.y)<48);$('crouchBtn').classList.toggle('active',crouching);$('lightBtn').classList.toggle('active',flashlight);$('runBtn').classList.toggle('active',!!(keys.shift||keys.run));if(monitor)drawFeed();
  }
  function toast(msg){$('toast').textContent=msg;$('toast').classList.add('show');toastTimer=2.2;}
  function whistle(){if(!running)return;if(whistleCooldown>0){toast(`WHISTLE RECHARGING · ${Math.ceil(whistleCooldown)}s`);return;}whistleCooldown=8;player.noise=4;beast.target=player;beast.state='INVESTIGATE';beast.alert=1;toast('WHISTLE ECHOES THROUGH THE FACILITY');}
  function toggleCrouch(){crouching=!crouching;if(crouching)toast('CROUCHING · QUIETER, HARDER TO SPOT');else toast('STANDING');}
  function interact(){if(!running)return;let loc=locFor(player.x,player.y);if(loc.id==='control'||loc.id==='controlLink'){openMonitor();return;}if(loc.id==='core'||loc.id==='coreLink'){openElevator();return;}}
  function openMonitor(){if(!running)return;monitor=true;$('monitorScreen').classList.remove('hidden');drawFeed();}
  function closeMonitor(){$('monitorScreen').classList.add('hidden');monitor=false;}
  function openElevator(){$('elevatorScreen').classList.remove('hidden');}
  function setFloor(n){floor=n;player.x=430;player.y=620;for(const b of bots){if(b.alive&&locFor(b.x,b.y).id==='core'){b.x=430+(Math.random()-.5)*100;b.y=620+(Math.random()-.5)*90;}}$('elevatorScreen').classList.add('hidden');toast(`ELEVATOR ARRIVED · CORE FLOOR ${String(n).padStart(2,'0')}`);floorChange=1.4;}
  function lose(){if(!running)return;running=false;$('endTag').textContent='CONTAINMENT FAILURE';$('endTitle').innerHTML='THE BEAST<br><em>FOUND YOU.</em>';$('endCopy').textContent='The facility goes quiet. Nobody made it out.';$('endScreen').classList.remove('hidden');}
  function win(){running=false;$('endTag').textContent='MISSION COMPLETE';$('endTitle').innerHTML='YOU MADE<br><em>IT OUT.</em>';$('endCopy').textContent=`You survived the breach with ${bots.filter(b=>b.alive).length} crew members still out there.`;$('endScreen').classList.remove('hidden');}
  function start(){player.x=212;player.y=420;player.alive=true;beast.x=165;beast.y=330;beast.target=null;beast.state='PATROL';beast.stun=0;timeLeft=180;stamina=100;floor=1;crouching=false;flashlight=false;monitor=false;bots.forEach((b,i)=>{b.alive=true;b.x=botStarts[i][0];b.y=botStarts[i][1];b.target=null;b.route=[];b.routeAt=0;b.hideTimer=0;b.crouch=false;b.decision=1+Math.random()*3;});running=true;$('introScreen').classList.add('hidden');$('endScreen').classList.add('hidden');toast('FIND COVER. THE BEAST IS LOOSE.');}
  function layout(){ctx.fillStyle='#0a1110';ctx.fillRect(0,0,W,H);ctx.strokeStyle='#111c19';ctx.lineWidth=1;for(let x=0;x<W;x+=30){ctx.beginPath();ctx.moveTo(x,0);ctx.lineTo(x,H);ctx.stroke()}for(let y=0;y<H;y+=30){ctx.beginPath();ctx.moveTo(0,y);ctx.lineTo(W,y);ctx.stroke()}
    // heavy exterior walls
    ctx.fillStyle='#1b2823';ctx.fillRect(48,88,1080,18);ctx.fillRect(48,720,1080,18);ctx.fillRect(48,88,18,650);ctx.fillRect(1110,88,18,650);
    for(const a of areas){let[x,y,w,h]=a.r;ctx.fillStyle=a.vent?'#101816':a.color;ctx.fillRect(x,y,w,h);if(!a.vent){ctx.fillStyle='#24342e';ctx.fillRect(x,y,w,5);ctx.fillRect(x,y+h-5,w,5);ctx.fillRect(x,y,5,h);ctx.fillRect(x+w-5,y,5,h);ctx.strokeStyle='#3b5146';ctx.lineWidth=1;ctx.strokeRect(x+5,y+5,w-10,h-10);}else{ctx.strokeStyle='#46514b';ctx.setLineDash([5,6]);ctx.strokeRect(x,y,w,h);ctx.setLineDash([]);ctx.fillStyle='#354039';ctx.font='7px monospace';if(w>80)ctx.fillText('AIR DUCT / LOW CLEARANCE',x+18,y+10);}}
    drawRoomLabels();drawObjects();drawTrain();
  }
  function drawRoomLabels(){ctx.save();ctx.textAlign='center';ctx.textBaseline='middle';ctx.font='800 16px "Barlow Condensed",sans-serif';ctx.fillStyle='#98afa1';ctx.globalAlpha=.6;const labels=[['LABORATORY',200,284],['CONTROL ROOM',545,172],['FREEZER ROOM',910,122],['RAILWAY',955,482],['THE CORE',435,545]];for(let [s,x,y]of labels)ctx.fillText(s,x,y);ctx.font='8px monospace';ctx.globalAlpha=.32;ctx.fillStyle='#c2d0c4';ctx.fillText('SECTOR A',200,302);ctx.fillText('SECTOR B',545,190);ctx.fillText('SECTOR C',910,140);ctx.restore();}
  function drawObjects(){// capsule
    ctx.save();ctx.translate(165,365);ctx.fillStyle='#07100f';ctx.fillRect(-28,-58,56,116);ctx.fillStyle='#263a33';ctx.fillRect(-26,-55,52,110);ctx.fillStyle='#93c4ac';ctx.globalAlpha=.27;ctx.beginPath();ctx.roundRect(-16,-42,32,84,16);ctx.fill();ctx.globalAlpha=1;ctx.strokeStyle='#a1d5bb';ctx.lineWidth=2;ctx.beginPath();ctx.roundRect(-16,-42,32,84,16);ctx.stroke();ctx.fillStyle='#8fe2ba';ctx.beginPath();ctx.ellipse(0,5,7,17,-.25,0,TAU);ctx.fill();ctx.strokeStyle='#ff594e';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(-20,-48);ctx.lineTo(-8,-18);ctx.lineTo(-14,4);ctx.lineTo(3,29);ctx.stroke();ctx.fillStyle='#ff594e';ctx.font='7px monospace';ctx.fillText('BREACH',0,70);ctx.restore();
    // consoles in control
    for(let i=0;i<4;i++){let x=458+i*42;ctx.fillStyle='#101b18';ctx.fillRect(x,236,34,35);ctx.fillStyle=i===1?'#8acdbc':'#547267';ctx.fillRect(x+5,241,24,14);ctx.fillStyle='#c5d069';ctx.fillRect(x+8,261,3,3);ctx.fillRect(x+15,261,3,3);}
    // freezer racks
    for(let i=0;i<3;i++){let y=162+i*39;ctx.fillStyle='#24434a';ctx.fillRect(810,y,160,6);ctx.fillRect(991,y,31,6);for(let j=0;j<4;j++){ctx.fillStyle='#7dbac1';ctx.globalAlpha=.34;ctx.fillRect(819+j*35,y-13,25,11);ctx.globalAlpha=1;}}
    // rail tracks and warning marks
    ctx.fillStyle='#414641';for(let y of [517,568,619]){ctx.fillRect(805,y,298,3);for(let x=810;x<1100;x+=22)ctx.fillRect(x,y-5,4,13);}ctx.fillStyle='#a85a37';for(let i=0;i<10;i++)ctx.fillRect(815+i*28,477,14,4);
    // core elevator
    ctx.fillStyle='#111a16';ctx.fillRect(378,572,104,96);ctx.strokeStyle='#9d9a70';ctx.strokeRect(378,572,104,96);ctx.fillStyle='#303c33';ctx.fillRect(417,578,25,84);ctx.fillStyle='#9ee0a4';ctx.fillRect(423,586,13,3);ctx.fillStyle='#a8b879';ctx.font='8px monospace';ctx.fillText(`FLOOR 0${floor}`,430,680);
    // hide locations
    for(const h of hides){ctx.save();ctx.translate(h.x,h.y);ctx.fillStyle=h.type==='locker'?'#477078':h.type==='rack'?'#40564a':h.type==='console'?'#3f5b52':'#534d3d';ctx.fillRect(-18,-14,36,28);ctx.strokeStyle='#849686';ctx.strokeRect(-18,-14,36,28);ctx.fillStyle='#b8c5a5';ctx.fillRect(-13,-9,26,2);ctx.fillStyle='#141b17';ctx.fillRect(-3,-8,6,22);ctx.restore();}
    // cold mist accents
    ctx.fillStyle='#a4f5ff';ctx.globalAlpha=.07;ctx.fillRect(785,110,250,170);ctx.globalAlpha=1;
  }
  function drawTrain(){ctx.save();let x=trainX;ctx.fillStyle='#121916';ctx.fillRect(x,487,250,66);ctx.fillStyle='#a44532';ctx.fillRect(x+4,491,242,58);ctx.fillStyle='#dd6f48';ctx.fillRect(x+12,497,226,5);for(let i=0;i<5;i++){ctx.fillStyle='#a6c5b5';ctx.globalAlpha=.68;ctx.fillRect(x+20+i*43,509,30,22);ctx.globalAlpha=1;}ctx.fillStyle='#161b18';for(let i=0;i<4;i++){ctx.beginPath();ctx.arc(x+38+i*58,556,8,0,TAU);ctx.fill()}ctx.fillStyle='#f8c46c';ctx.fillRect(x+237,514,7,6);ctx.restore();}

  function drawPerson(e,color,isBeast=false){ctx.save();ctx.translate(e.x,e.y);ctx.rotate(e.face||0);if(isBeast){ctx.fillStyle='#e8483f';ctx.shadowColor='#ef4539';ctx.shadowBlur=16;ctx.beginPath();ctx.ellipse(0,0,18,13,0,0,TAU);ctx.fill();ctx.shadowBlur=0;ctx.fillStyle='#331814';ctx.beginPath();ctx.moveTo(-9,-7);ctx.lineTo(-23,-17);ctx.lineTo(-18,-3);ctx.lineTo(-23,9);ctx.lineTo(-8,7);ctx.fill();ctx.fillStyle='#ffcb89';ctx.fillRect(7,-5,3,3);ctx.fillRect(7,3,3,3);ctx.strokeStyle='#ff7a56';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(-2,9);ctx.lineTo(-3,17);ctx.moveTo(6,8);ctx.lineTo(9,15);ctx.stroke();}else{ctx.fillStyle='#030807';ctx.beginPath();ctx.ellipse(1,3,9,7,0,0,TAU);ctx.fill();ctx.fillStyle=color;ctx.beginPath();ctx.arc(0,0,7,0,TAU);ctx.fill();ctx.fillStyle='#e9eee4';ctx.beginPath();ctx.arc(3,-2,2,0,TAU);ctx.fill();ctx.strokeStyle=color;ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(-2,4);ctx.lineTo(-7,9);ctx.moveTo(3,4);ctx.lineTo(7,9);ctx.stroke();}ctx.restore();}
