  function start(){player.x=212;player.y=420;player.alive=true;player.hidden=false;beast.x=165;beast.y=365;beast.target=null;beast.state='PATROL';beast.stun=0;huntDelay=5;timeLeft=180;stamina=100;floor=1;crouching=false;flashlight=false;monitor=false;bots.forEach((b,i)=>{b.alive=true;b.x=botStarts[i][0];b.y=botStarts[i][1];b.target=null;b.route=[];b.routeAt=0;b.hideTimer=0;b.crouch=false;b.decision=1+Math.random()*3;});running=true;$('introScreen').classList.add('hidden');$('endScreen').classList.add('hidden');toast('FIND COVER. THE BEAST IS LOOSE.');}
  function drawPerson(e,color,isBeast=false){ctx.save();ctx.translate(e.x,e.y);ctx.rotate(e.face||0);if(isBeast){ctx.fillStyle='#e8483f';ctx.shadowColor='#ef4539';ctx.shadowBlur=16;ctx.beginPath();ctx.ellipse(0,0,18,13,0,0,TAU);ctx.fill();ctx.shadowBlur=0;ctx.fillStyle='#331814';ctx.beginPath();ctx.moveTo(-9,-7);ctx.lineTo(-23,-17);ctx.lineTo(-18,-3);ctx.lineTo(-23,9);ctx.lineTo(-8,7);ctx.fill();ctx.fillStyle='#ffcb89';ctx.fillRect(7,-5,3,3);ctx.fillRect(7,3,3,3);ctx.strokeStyle='#ff7a56';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(-2,9);ctx.lineTo(-3,17);ctx.moveTo(6,8);ctx.lineTo(9,15);ctx.stroke();}else{ctx.fillStyle='#030807';ctx.beginPath();ctx.ellipse(1,3,9,7,0,0,TAU);ctx.fill();ctx.fillStyle=color;ctx.beginPath();ctx.arc(0,0,7,0,TAU);ctx.fill();ctx.fillStyle='#e9eee4';ctx.beginPath();ctx.arc(3,-2,2,0,TAU);ctx.fill();ctx.strokeStyle=color;ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(-2,4);ctx.lineTo(-7,9);ctx.moveTo(3,4);ctx.lineTo(7,9);ctx.stroke();}ctx.restore();}
  function drawEntities(){for(const b of bots){if(!b.alive)continue;drawPerson(b,b.color);if(Math.hypot(b.x-player.x,b.y-player.y)<100){ctx.font='7px monospace';ctx.textAlign='center';ctx.fillStyle='#d5e0d7';ctx.fillText(b.name,b.x,b.y-14);}}drawPerson(beast,'#f25242',true);if(player.hidden)ctx.globalAlpha=.4;drawPerson(player,'#c7f36a');ctx.globalAlpha=1;if(flashlight){ctx.save();ctx.strokeStyle='#d6f7a4';ctx.globalAlpha=.5;ctx.beginPath();ctx.moveTo(player.x,player.y);ctx.arc(player.x,player.y,96,player.face-.55,player.face+.55);ctx.closePath();ctx.stroke();ctx.restore();}}
  function drawDarkness(){ctx.save();ctx.fillStyle='rgba(0,0,0,.43)';ctx.fillRect(0,0,W,H);ctx.globalCompositeOperation='destination-out';let r=player.hidden?65:flashlight?210:110,g=ctx.createRadialGradient(player.x,player.y,6,player.x,player.y,r);g.addColorStop(0,'rgba(0,0,0,.98)');g.addColorStop(.7,'rgba(0,0,0,.55)');g.addColorStop(1,'rgba(0,0,0,0)');ctx.fillStyle=g;ctx.beginPath();ctx.arc(player.x,player.y,r,0,TAU);ctx.fill();ctx.restore();for(const a of areas.filter(a=>a.vent)){ctx.save();ctx.fillStyle='rgba(0,0,0,.56)';ctx.fillRect(...a.r);if(flashlight){let[x,y,w,h]=a.r,g=ctx.createRadialGradient(player.x,player.y,0,player.x,player.y,155);g.addColorStop(0,'rgba(0,0,0,.82)');g.addColorStop(1,'rgba(0,0,0,0)');ctx.globalCompositeOperation='destination-out';ctx.fillStyle=g;ctx.fillRect(x-30,y-30,w+60,h+60);}ctx.restore();}}
  function layout(){ctx.fillStyle='#0a1110';ctx.fillRect(0,0,W,H);ctx.strokeStyle='#111c19';ctx.lineWidth=1;for(let x=0;x<W;x+=30){ctx.beginPath();ctx.moveTo(x,0);ctx.lineTo(x,H);ctx.stroke();}for(let y=0;y<H;y+=30){ctx.beginPath();ctx.moveTo(0,y);ctx.lineTo(W,y);ctx.stroke();}ctx.fillStyle='#1b2823';ctx.fillRect(48,88,1080,18);ctx.fillRect(48,720,1080,18);ctx.fillRect(48,88,18,650);ctx.fillRect(1110,88,18,650);
    for(const a of areas){let[x,y,w,h]=a.r;ctx.fillStyle=a.vent?'#101816':a.color;ctx.fillRect(x,y,w,h);if(!a.vent){ctx.fillStyle='#24342e';ctx.fillRect(x,y,w,5);ctx.fillRect(x,y+h-5,w,5);ctx.fillRect(x,y,5,h);ctx.fillRect(x+w-5,y,5,h);ctx.strokeStyle='#3b5146';ctx.lineWidth=1;ctx.strokeRect(x+5,y+5,w-10,h-10);}else{ctx.strokeStyle='#46514b';ctx.setLineDash([5,6]);ctx.strokeRect(x,y,w,h);ctx.setLineDash([]);if(w>80){ctx.fillStyle='#354039';ctx.font='7px monospace';ctx.fillText('AIR DUCT / LOW CLEARANCE',x+18,y+10);}}}
    ctx.save();ctx.textAlign='center';ctx.textBaseline='middle';ctx.font='800 16px "Barlow Condensed",sans-serif';ctx.fillStyle='#98afa1';ctx.globalAlpha=.62;for(const[s,x,y]of[['LABORATORY',200,284],['CONTROL ROOM',545,172],['FREEZER ROOM',910,122],['RAILWAY',955,482],['THE CORE',435,545]])ctx.fillText(s,x,y);ctx.restore();drawObjects();drawTrain();}
  function drawObjects(){ctx.save();ctx.translate(165,365);ctx.fillStyle='#263a33';ctx.fillRect(-26,-55,52,110);ctx.fillStyle='#93c4ac';ctx.globalAlpha=.27;ctx.beginPath();ctx.roundRect(-16,-42,32,84,16);ctx.fill();ctx.globalAlpha=1;ctx.strokeStyle='#a1d5bb';ctx.lineWidth=2;ctx.beginPath();ctx.roundRect(-16,-42,32,84,16);ctx.stroke();ctx.fillStyle='#8fe2ba';ctx.beginPath();ctx.ellipse(0,5,7,17,-.25,0,TAU);ctx.fill();ctx.strokeStyle='#ff594e';ctx.beginPath();ctx.moveTo(-20,-48);ctx.lineTo(-8,-18);ctx.lineTo(-14,4);ctx.lineTo(3,29);ctx.stroke();ctx.restore();
    for(let i=0;i<4;i++){let x=458+i*42;ctx.fillStyle='#101b18';ctx.fillRect(x,236,34,35);ctx.fillStyle=i===1?'#8acdbc':'#547267';ctx.fillRect(x+5,241,24,14);ctx.fillStyle='#c5d069';ctx.fillRect(x+8,261,3,3);ctx.fillRect(x+15,261,3,3);}for(let i=0;i<3;i++){let y=162+i*39;ctx.fillStyle='#24434a';ctx.fillRect(810,y,160,6);for(let j=0;j<4;j++){ctx.fillStyle='#7dbac1';ctx.globalAlpha=.34;ctx.fillRect(819+j*35,y-13,25,11);ctx.globalAlpha=1;}}
    ctx.fillStyle='#414641';for(let y of[517,568,619]){ctx.fillRect(805,y,298,3);for(let x=810;x<1100;x+=22)ctx.fillRect(x,y-5,4,13);}ctx.fillStyle='#111a16';ctx.fillRect(378,572,104,96);ctx.strokeStyle='#9d9a70';ctx.strokeRect(378,572,104,96);ctx.fillStyle='#303c33';ctx.fillRect(417,578,25,84);ctx.fillStyle='#9ee0a4';ctx.fillRect(423,586,13,3);ctx.fillStyle='#a8b879';ctx.font='8px monospace';ctx.fillText(`FLOOR 0${floor}`,430,680);
    for(const h of hides){ctx.save();ctx.translate(h.x,h.y);ctx.fillStyle=h.type==='locker'?'#477078':h.type==='rack'?'#40564a':h.type==='console'?'#3f5b52':'#534d3d';ctx.fillRect(-18,-14,36,28);ctx.strokeStyle='#849686';ctx.strokeRect(-18,-14,36,28);ctx.fillStyle='#b8c5a5';ctx.fillRect(-13,-9,26,2);ctx.restore();}ctx.fillStyle='rgba(164,245,255,.07)';ctx.fillRect(785,110,250,170);}
  function drawTrain(){ctx.fillStyle='#121916';ctx.fillRect(trainX,487,250,66);ctx.fillStyle='#a44532';ctx.fillRect(trainX+4,491,242,58);ctx.fillStyle='#dd6f48';ctx.fillRect(trainX+12,497,226,5);for(let i=0;i<5;i++){ctx.fillStyle='#a6c5b5';ctx.globalAlpha=.68;ctx.fillRect(trainX+20+i*43,509,30,22);ctx.globalAlpha=1;}ctx.fillStyle='#161b18';for(let i=0;i<4;i++){ctx.beginPath();ctx.arc(trainX+38+i*58,556,8,0,TAU);ctx.fill();}}
  function drawMinimap(){mctx.clearRect(0,0,mini.width,mini.height);mctx.fillStyle='#08110e';mctx.fillRect(0,0,mini.width,mini.height);mctx.save();mctx.scale(mini.width/W,mini.height/H);for(const a of areas.filter(a=>!a.vent)){mctx.fillStyle=a.id==='freezer'?'#34575d':a.id==='core'?'#4b4430':'#294139';mctx.fillRect(...a.r);}for(const a of areas.filter(a=>a.vent)){mctx.fillStyle='#74827a';mctx.fillRect(...a.r);}for(const b of bots)if(b.alive){mctx.fillStyle='#83d9cb';mctx.beginPath();mctx.arc(b.x,b.y,6,0,TAU);mctx.fill();}mctx.fillStyle='#ff594e';mctx.beginPath();mctx.arc(beast.x,beast.y,9,0,TAU);mctx.fill();mctx.fillStyle='#c7f36a';mctx.beginPath();mctx.arc(player.x,player.y,7,0,TAU);mctx.fill();mctx.restore();}
  function render(){let cw=innerWidth,ch=innerHeight;ctx.setTransform(dpr,0,0,dpr,0,0);ctx.clearRect(0,0,cw,ch);ctx.fillStyle='#070d0c';ctx.fillRect(0,0,cw,ch);ctx.save();ctx.translate(ox,oy);ctx.scale(scale,scale);layout();drawEntities();drawDarkness();if(beast.state==='CHASE'&&Math.hypot(beast.x-player.x,beast.y-player.y)<220){ctx.fillStyle='rgba(255,58,43,.08)';ctx.fillRect(0,0,W,H);}ctx.restore();drawMinimap();requestAnimationFrame(render);}
  const cameras=[{name:'LABORATORY',x:200,y:380},{name:'CONTROL ROOM',x:545,y:225},{name:'FREEZER',x:900,y:195},{name:'RAIL PLATFORM',x:955,y:550},{name:'CORE SHAFT',x:430,y:620}];
  function drawFeed(){if(!monitor)return;const cam=cameras[camIndex];$('feedLabel').textContent=`CAM 0${camIndex+1} · ${cam.name}`;fctx.fillStyle='#09110f';fctx.fillRect(0,0,640,360);let s=1.1,left=cam.x-640/(2*s),top=cam.y-360/(2*s);fctx.save();fctx.scale(s,s);fctx.translate(-left,-top);for(const a of areas){if(a.vent)continue;fctx.fillStyle=a.id==='freezer'?'#24424a':'#25342d';fctx.fillRect(...a.r);fctx.strokeStyle='#42564b';fctx.strokeRect(...a.r);}for(const h of hides){fctx.fillStyle='#657565';fctx.fillRect(h.x-7,h.y-6,14,12);}for(const b of bots)if(b.alive){fctx.fillStyle=b.color;fctx.beginPath();fctx.arc(b.x,b.y,7,0,TAU);fctx.fill();}fctx.fillStyle='#f25345';fctx.beginPath();fctx.arc(beast.x,beast.y,11,0,TAU);fctx.fill();fctx.fillStyle='#c7f36a';fctx.beginPath();fctx.arc(player.x,player.y,8,0,TAU);fctx.fill();fctx.restore();fctx.fillStyle='rgba(9,16,13,.12)';for(let y=0;y<360;y+=4)fctx.fillRect(0,y,640,1);fctx.strokeStyle='rgba(135,221,196,.25)';fctx.strokeRect(7,7,626,346);}
  function buildCameras(){let list=$('camList');list.innerHTML='';cameras.forEach((c,i)=>{let b=document.createElement('button');b.className='cam-choice'+(i===camIndex?' active':'');b.innerHTML=`CAM 0${i+1}<b>${c.name}</b>`;b.onclick=()=>{camIndex=i;buildCameras();drawFeed();};list.appendChild(b);});}
  function buildFloors(){let e=$('floorButtons');for(let i=1;i<=5;i++){let b=document.createElement('button');b.className='floor-btn';b.textContent=String(i).padStart(2,'0');b.onclick=()=>setFloor(i);e.appendChild(b);}}
  function bindControls(){addEventListener('keydown',e=>{let k=e.key.toLowerCase();keys[k]=true;if(['arrowup','arrowdown','arrowleft','arrowright',' '].includes(k))e.preventDefault();if(!running)return;if(k==='f'){flashlight=!flashlight;toast(flashlight?'FLASHLIGHT ON':'FLASHLIGHT OFF');}if(k==='q')whistle();if(k==='control'&&!e.repeat)toggleCrouch();if(k==='e'&&!e.repeat)interact();if(k==='escape'){closeMonitor();$('elevatorScreen').classList.add('hidden');}});addEventListener('keyup',e=>{keys[e.key.toLowerCase()]=false;});$('startBtn').onclick=start;$('againBtn').onclick=start;$('crouchBtn').onclick=toggleCrouch;$('runBtn').onpointerdown=e=>{e.preventDefault();keys.run=true;};$('runBtn').onpointerup=()=>keys.run=false;$('runBtn').onpointercancel=()=>keys.run=false;$('lightBtn').onclick=()=>{flashlight=!flashlight;toast(flashlight?'FLASHLIGHT ON':'FLASHLIGHT OFF');};$('whistleBtn').onclick=whistle;$('monitorOpen').onclick=openMonitor;$('monitorClose').onclick=closeMonitor;$('elevatorClose').onclick=()=>$('elevatorScreen').classList.add('hidden');$('soundBtn').onclick=()=>{muted=!muted;$('soundBtn').innerHTML=muted?'♫ <span>SOUND</span>':'♫ <span>ON</span>';toast(muted?'SOUND MUTED':'SOUND ON');};document.querySelectorAll('.mobile-pad button').forEach(b=>{let d=b.dataset.dir,down=e=>{e.preventDefault();touch[d]=true;},up=e=>{e.preventDefault();touch[d]=false;};b.addEventListener('pointerdown',down);b.addEventListener('pointerup',up);b.addEventListener('pointerleave',up);b.addEventListener('pointercancel',up);});}
  function buildUI(){buildCameras();buildFloors();bindControls();}
  let huntDelay=0;
  const originalUpdateBeast=updateBeast;
  updateBeast=function(dt){if(huntDelay>0){huntDelay=Math.max(0,huntDelay-dt);return;}originalUpdateBeast(dt);};
  buildUI();
  let last=performance.now();function loop(now){let dt=Math.min(.05,(now-last)/1000);last=now;update(dt);requestAnimationFrame(loop);}requestAnimationFrame(loop);requestAnimationFrame(render);
})();

