   botStarts.forEach((p,i)=>bots.push(bot(p[0],p[1],i)));
   function resize(){dpr=Math.min(devicePixelRatio||1,2);canvas.width=Math.floor(innerWidth*dpr);canvas.height=Math.floor(innerHeight*dpr);ctx.setTransform(dpr,0,0,dpr,0,0);scale=Math.min(innerWidth/W,innerHeight/H);ox=(innerWidth-W*scale)/2;oy=(innerHeight-H*scale)/2;}
   addEventListener('resize',resize);resize();
   function inside(x,y,r){return x>=r[0]&&x<=r[0]+r[2]&&y>=r[1]&&y<=r[1]+r[3];}
-  function areaAt(x,y){return areas.find(a=>inside(x,y,a.r))||areas[0];}
+  function areaAt(x,y){return areas.find(a=>a.vent&&inside(x,y,a.r))||areas.find(a=>inside(x,y,a.r))||areas[0];}
   function walkable(x,y){return areas.some(a=>inside(x,y,a.r));}
   function moveEntity(e,dx,dy){let nx=e.x+dx,ny=e.y+dy;if(walkable(nx,e.y))e.x=nx;if(walkable(e.x,ny))e.y=ny;}
   function clampEntity(e){if(walkable(e.x,e.y))return;let best=null,bd=Infinity;for(let a of areas){let[x,y,w,h]=a.r,cx=Math.max(x+3,Math.min(x+w-3,e.x)),cy=Math.max(y+3,Math.min(y+h-3,e.y)),d=(cx-e.x)**2+(cy-e.y)**2;if(d<bd){bd=d;best=[cx,cy];}}if(best){e.x=best[0];e.y=best[1];}}
   function graphRoute(from,to){let si=0,ti=0,sd=Infinity,td=Infinity;nodes.forEach((n,i)=>{let a=(n.x-from.x)**2+(n.y-from.y)**2,b=(n.x-to.x)**2+(n.y-to.y)**2;if(a<sd){sd=a;si=i}if(b<td){td=b;ti=i}});let q=[si],prev={[si]:-1};while(q.length){let n=q.shift();if(n===ti)break;for(const[a,b]of links){let next=a===n?b:b===n?a:-1;if(next>=0&&prev[next]===undefined){prev[next]=n;q.push(next);}}}let path=[];if(prev[ti]!==undefined){let n=ti;while(n!==-1){path.unshift(nodes[n]);n=prev[n];}}return path;}
